    const desRoll = clamp(-Math.asin(clamp(Fz / Fmag, -0.9, 0.9)), -0.55, 0.55);
    const desPitchRate = clamp((Fy * dFx - Fx * dFy) / Fxy2, -8, 8);
    const desRollRate = clamp(-(dFz * Fmag - Fz * dFmag) / (Fmag * Fxy), -8, 8);

