  return {
    t: 0, pos: { x: TAKEOFF.x + parameters.offset.x, y: TASK.bodyHeight, z: TAKEOFF.z + parameters.offset.z },
    vel: { x: 0, y: 0, z: 0 }, att: { roll: 0, pitch: 0, yaw: 0 },
    rates: { roll: 0, pitch: 0, yaw: 0 }, motors: [0, 0, 0, 0], integral: { roll: 0, pitch: 0 },
    gateIndex: 0, landedFor: 0, airborne: false, reason: null,
  };
}

function integrate(state, action, parameters, dt) {
  const old = copy(state.pos), { att, rates } = state;
  const inertia = TASK.inertia * parameters.mass / TASK.baseMass;
  const torque = {};
  for (const axis of ["roll", "pitch"]) {
    const error = action[axis] - att[axis];
    state.integral[axis] = clamp(state.integral[axis] + error * dt, -0.35, 0.35);
    torque[axis] = inertia * (65 * error - 13 * rates[axis] + 22 * state.integral[axis]);
  }
  torque.yaw = inertia * 8 * (action.yawRate - rates.yaw);
  for (let i = 0; i < 4; i++) {
    const desired = action.thrust * TASK.maxMotorThrust +
      torque.roll * MOTOR_Z[i] / (4 * TASK.arm) - torque.pitch * MOTOR_X[i] / (4 * TASK.arm) +
      torque.yaw * SPIN[i] / (4 * TASK.yawCoefficient);
    const target = clamp(desired, 0, TASK.maxMotorThrust) * (i === parameters.weakMotor ? 1 - parameters.weakness : 1);
    state.motors[i] += (target - state.motors[i]) * (1 - Math.exp(-dt / parameters.lag));
  }
  const sum = state.motors.reduce((a, b) => a + b, 0);
  const moment = (sign) => state.motors.reduce((a, f, i) => a + f * sign[i], 0);
  rates.roll += (TASK.arm * moment(MOTOR_Z) / inertia - 0.4 * rates.roll) * dt;
  rates.pitch += (-TASK.arm * moment(MOTOR_X) / inertia - 0.4 * rates.pitch) * dt;
  rates.yaw += (TASK.yawCoefficient * moment(SPIN) / inertia - 0.4 * rates.yaw) * dt;
  for (const axis of ["roll", "pitch", "yaw"]) att[axis] += rates[axis] * dt;
  const bodyX = Math.sin(att.pitch) * Math.cos(att.roll), bodyZ = -Math.sin(att.roll);
  const direction = { x: Math.cos(att.yaw) * bodyX + Math.sin(att.yaw) * bodyZ,
    y: Math.cos(att.pitch) * Math.cos(att.roll), z: -Math.sin(att.yaw) * bodyX + Math.cos(att.yaw) * bodyZ };
  const wind = copy(parameters.baseWind);
  for (const gust of parameters.gusts) if (state.t >= gust.start && state.t < gust.start + gust.duration) {
    wind.x += gust.x; wind.y += gust.y; wind.z += gust.z;
  }
  for (const axis of ["x", "y", "z"]) {
    const force = sum * direction[axis] + TASK.linearDrag * (wind[axis] - state.vel[axis]);
    state.vel[axis] += (force / parameters.mass - (axis === "y" ? TASK.gravity : 0)) * dt;
    state.pos[axis] += state.vel[axis] * dt;
  }
  state.t += dt;
  if (state.pos.y > TASK.bodyHeight + 0.08) state.airborne = true;
  if (Math.max(Math.abs(att.roll), Math.abs(att.pitch)) > TASK.flipAngle) state.reason = "flipped";
  if (Math.abs(state.pos.x) + TASK.bodyRadius >= TASK.room.maxX || Math.abs(state.pos.z) + TASK.bodyRadius >= TASK.room.maxZ || state.pos.y + TASK.bodyHeight >= TASK.room.height) {
    if (norm(state.vel) > TASK.contactCrashSpeed) state.reason = "wall or ceiling crash";
    state.pos.x = clamp(state.pos.x, TASK.room.minX + TASK.bodyRadius, TASK.room.maxX - TASK.bodyRadius);
    state.pos.z = clamp(state.pos.z, TASK.room.minZ + TASK.bodyRadius, TASK.room.maxZ - TASK.bodyRadius);
    state.pos.y = Math.min(state.pos.y, TASK.room.height - TASK.bodyHeight);
    state.vel.x = 0; state.vel.z = 0; state.vel.y = Math.min(state.vel.y, 0);
  }
  if (state.pos.y <= TASK.bodyHeight) {
    if (state.airborne && (norm(state.vel) > TASK.contactCrashSpeed || Math.max(Math.abs(att.roll), Math.abs(att.pitch)) > TASK.landingTilt * 2)) state.reason = "floor crash";
    state.pos.y = TASK.bodyHeight; state.vel.y = Math.max(0, state.vel.y);
    state.vel.x *= Math.exp(-12 * dt); state.vel.z *= Math.exp(-12 * dt);
  }
  for (let i = 0; i < GATES.length; i++) {
    const gate = GATES[i], x = gate.centre.x;
    if ((old.x < x && state.pos.x >= x) || (old.x > x && state.pos.x <= x)) {
      const fraction = (x - old.x) / (state.pos.x - old.x);
      const y = old.y + fraction * (state.pos.y - old.y), z = old.z + fraction * (state.pos.z - old.z);
      const dy = Math.abs(y - gate.centre.y), dz = Math.abs(z - gate.centre.z);
      const half = TASK.gateOpening / 2, outer = half + TASK.gateFrame;
      const fits = dy + TASK.bodyHeight <= half && dz + TASK.bodyRadius <= half;
      const overlapsFrame = dy <= outer + TASK.bodyHeight && dz <= outer + TASK.bodyRadius && !fits;
      if (overlapsFrame) state.reason = "gate frame collision";
      if (i === state.gateIndex && old.x < x && state.pos.x >= x && fits) state.gateIndex++;
    }
  }
  const error = Math.hypot(state.pos.x - PAD.centre.x, state.pos.z - PAD.centre.z);
  if (state.gateIndex === GATES.length && error <= TASK.landingRadius && state.pos.y <= TASK.bodyHeight + 0.025 &&
      norm(state.vel) < TASK.landingSpeed && Math.max(Math.abs(att.roll), Math.abs(att.pitch)) < TASK.landingTilt) state.landedFor += dt;
  else state.landedFor = 0;
  if (state.landedFor >= TASK.landingHold && !state.reason) state.reason = "landed";
}

function evalQuintic1D(p0, v0, a0, p1, v1, a1, T, tau) {
  const c0 = p0, c1 = v0, c2 = 0.5 * a0;
  const T2 = T * T, T3 = T2 * T, T4 = T3 * T, T5 = T4 * T;
  const dp = p1 - (p0 + v0 * T + 0.5 * a0 * T2);
  const dv = v1 - (v0 + a0 * T);
  const da = a1 - a0;
  const c3 = (10 * dp) / T3 - (4 * dv) / T2 + da / (2 * T);
  const c4 = (-15 * dp) / T4 + (7 * dv) / T3 - da / T2;
  const c5 = (6 * dp) / T5 - (3 * dv) / T4 + da / (2 * T3);
  const t2 = tau * tau, t3 = t2 * tau, t4 = t3 * tau, t5 = t4 * tau;
  return {
    p: c0 + c1 * tau + c2 * t2 + c3 * t3 + c4 * t4 + c5 * t5,
    v: c1 + 2 * c2 * tau + 3 * c3 * t2 + 4 * c4 * t3 + 5 * c5 * t4,
    a: 2 * c2 + 6 * c3 * tau + 12 * c4 * t2 + 20 * c5 * t3,
    j: 6 * c3 + 24 * c4 * tau + 60 * c5 * t2,
  };
}

function smoothStep(u) {
  if (u <= -1) return { s: 0, ds: 0 };
  if (u >= 1) return { s: 1, ds: 0 };
  const u2 = u * u, u3 = u2 * u, u5 = u3 * u2;
  const t = 1 - u2;
  return {
    s: 0.5 + 0.9375 * u - 0.625 * u3 + 0.1875 * u5,
    ds: 0.9375 * t * t,
  };
}

function getLookaheadWind(params, t, lead, halfW, minDur = 0) {
  let wx = params.baseWind.x, wz = params.baseWind.z;
  let dwx = 0, dwz = 0;
  for (const g of params.gusts) {
    if (g.duration < minDur) continue;
    const on = smoothStep((t - (g.start - lead)) / halfW);
    const off = smoothStep((t - (g.start + g.duration - lead)) / halfW);
    const w = on.s - off.s;
    const dw = (on.ds - off.ds) / halfW;
    wx += g.x * w; wz += g.z * w;
    dwx += g.x * dw; dwz += g.z * dw;
  }
  return { x: wx, y: 0, z: wz, dx: dwx, dy: 0, dz: dwz };
}

function gustPenalty(params, t) {
  let pen = 0;
  for (const g of params.gusts) {
    const s = g.start, e = g.start + g.duration;
    const mag = Math.hypot(g.x, g.z);
    if (t >= s - 0.08 && t <= e) {
      pen += mag * 3.0 * (1 + (t - s) * 0.5);
    } else if (t > e && t <= e + 0.85) {
      const rem = 1 - (t - e) / 0.85;
      pen += mag * 3.0 * rem;
    }
  }
  return pen;
}

function chooseSchedule(params) {
  let best = [2.1, 4.3, 6.5, 9.0], bestCost = 1e9;
  const minD1 = params.mass / (1 - params.weakness) > 1.15 ? 2.0 : 1.75;
  for (let d1 = minD1; d1 <= 3.0; d1 += 0.12) {
    const t1 = d1;
    const p1 = gustPenalty(params, t1) + 0.4 * (d1 - 2.1) * (d1 - 2.1);
    for (let d2 = 1.75; d2 <= 3.5; d2 += 0.12) {
      const t2 = t1 + d2;
      const p2 = p1 + gustPenalty(params, t2) + 0.4 * (d2 - 2.2) * (d2 - 2.2);
      for (let d3 = 1.75; d3 <= 3.5; d3 += 0.12) {
        const t3 = t2 + d3;
        const p3 = p2 + gustPenalty(params, t3) + 0.4 * (d3 - 2.2) * (d3 - 2.2);
        const d4 = 2.4;
        const t4 = t3 + d4;
        if (t4 > 12.6) continue;
        const cost = p3 + 0.3 * gustPenalty(params, t4);
        if (cost < bestCost) {
          bestCost = cost;
          best = [t1, t2, t3, t4];
        }
      }
    }
  }
  return best;
}

function wrapAngle(a) {
  while (a > Math.PI) a -= 2 * Math.PI;
  while (a < -Math.PI) a += 2 * Math.PI;
  return a;
}

function runTest(seed) {
  const params = trialParameters(seed);
  const simState = initialState(params);
  const myState = initialState(params);

  const [t1, t2, t3, t4] = chooseSchedule(params);
  const waypoints = [
    { t: 0.0, p: copy(myState.pos), v: { x: 0, y: 0, z: 0 }, a: { x: 0, y: 0, z: 0 } },
    { t: t1, p: { x: -1.15, y: 1.05, z: -0.85 }, v: { x: 0.55, y: 0.10, z: 0.35 }, a: { x: 0, y: 0, z: 0 } },
    { t: t2, p: { x: 0.15, y: 1.40, z: 0.25 }, v: { x: 0.55, y: 0.0, z: 0.35 }, a: { x: 0, y: 0, z: 0 } },
    { t: t3, p: { x: 1.35, y: 1.05, z: 1.05 }, v: { x: 0.48, y: -0.05, z: 0.28 }, a: { x: 0, y: 0, z: 0 } },
    { t: t4, p: { x: 2.05, y: 0.086, z: 1.65 }, v: { x: 0, y: 0, z: 0 }, a: { x: 0, y: 0, z: 0 } },
  ];

  const wIdx = params.weakMotor;
  const cornerAngle = Math.atan2(MOTOR_Z[wIdx], MOTOR_X[wIdx]);

  function getRef(t) {
    const last = waypoints[waypoints.length - 1];
    if (t >= last.t) return { p: copy(last.p), v: { x: 0, y: 0, z: 0 }, a: { x: 0, y: 0, z: 0 }, j: { x: 0, y: 0, z: 0 } };
    let k = 0;
    while (k < waypoints.length - 2 && t >= waypoints[k + 1].t) k++;
    const w0 = waypoints[k], w1 = waypoints[k + 1];
    const T = w1.t - w0.t, tau = t - w0.t;
    const rx = evalQuintic1D(w0.p.x, w0.v.x, w0.a.x, w1.p.x, w1.v.x, w1.a.x, T, tau);
    const ry = evalQuintic1D(w0.p.y, w0.v.y, w0.a.y, w1.p.y, w1.v.y, w1.a.y, T, tau);
    const rz = evalQuintic1D(w0.p.z, w0.v.z, w0.a.z, w1.p.z, w1.v.z, w1.a.z, T, tau);
    return {
      p: { x: rx.p, y: ry.p, z: rz.p },
      v: { x: rx.v, y: ry.v, z: rz.v },
      a: { x: rx.a, y: ry.a, z: rz.a },
      j: { x: rx.j, y: ry.j, z: rz.j },
    };
  }

  let desYaw = 0;
  for (let step = 0; step < 1500 && !simState.reason; step++) {
    const s = myState;
    const ref = getRef(s.t);
    const w = getLookaheadWind(params, s.t, 0.05, 0.05, 0);
    const wFar = getLookaheadWind(params, s.t, 0.30, 0.20, 0.5);
    const windForceX = -TASK.linearDrag * (wFar.x - ref.v.x);
    const windForceZ = -TASK.linearDrag * (wFar.z - ref.v.z);
    if (Math.hypot(windForceX, windForceZ) > 0.8) {
      const worldThrustAngle = Math.atan2(windForceZ, windForceX);
      const targetYaw = wrapAngle(cornerAngle - worldThrustAngle);
      desYaw += clamp(wrapAngle(targetYaw - desYaw), -0.02, 0.02);
    }

    const sumM = s.motors[0] + s.motors[1] + s.motors[2] + s.motors[3];
    const bx = Math.sin(s.att.pitch) * Math.cos(s.att.roll), bz = -Math.sin(s.att.roll);
    const cy = Math.cos(s.att.yaw), sy = Math.sin(s.att.yaw);
    const dir = {
      x: cy * bx + sy * bz,
      y: Math.cos(s.att.pitch) * Math.cos(s.att.roll),
      z: -sy * bx + cy * bz,
    };
    const curAcc = {
      x: (sumM * dir.x + TASK.linearDrag * (w.x - s.vel.x)) / params.mass,
      y: (sumM * dir.y + TASK.linearDrag * (w.y - s.vel.y)) / params.mass - TASK.gravity,
      z: (sumM * dir.z + TASK.linearDrag * (w.z - s.vel.z)) / params.mass,
    };

    const kp = 18.0, kd = 8.2, kja = 2.0;
    const kpy = 18.0, kdy = 8.5;
    const ades = {
      x: ref.a.x + kp * (ref.p.x - s.pos.x) + kd * (ref.v.x - s.vel.x),
      y: ref.a.y + kpy * (ref.p.y - s.pos.y) + kdy * (ref.v.y - s.vel.y),
      z: ref.a.z + kp * (ref.p.z - s.pos.z) + kd * (ref.v.z - s.vel.z),
    };
    const jdes = {
      x: ref.j.x + kp * (ref.v.x - s.vel.x) + kja * (ref.a.x - curAcc.x),
      y: ref.j.y + kpy * (ref.v.y - s.vel.y) + kja * (ref.a.y - curAcc.y),
      z: ref.j.z + kp * (ref.v.z - s.vel.z) + kja * (ref.a.z - curAcc.z),
    };

    const Fx = params.mass * ades.x - TASK.linearDrag * (w.x - s.vel.x);
    const Fy = Math.max(1.5, params.mass * (ades.y + TASK.gravity) - TASK.linearDrag * (w.y - s.vel.y));
    const Fz = params.mass * ades.z - TASK.linearDrag * (w.z - s.vel.z);

    const dFx = params.mass * jdes.x - TASK.linearDrag * (w.dx - ades.x);
    const dFy = params.mass * jdes.y - TASK.linearDrag * (w.dy - ades.y);
    const dFz = params.mass * jdes.z - TASK.linearDrag * (w.dz - ades.z);

    const Fbx = cy * Fx - sy * Fz;
    const Fbz = sy * Fx + cy * Fz;
    const dFbx = cy * dFx - sy * dFz - s.rates.yaw * Fbz;
    const dFbz = sy * dFx + cy * dFz + s.rates.yaw * Fbx;

    const Fxy2 = Fbx * Fbx + Fy * Fy;
    const Fxy = Math.sqrt(Fxy2);
    const FmagRaw = Math.sqrt(Fxy2 + Fbz * Fbz);
    const dFmag = (Fbx * dFbx + Fy * dFy + Fbz * dFbz) / FmagRaw;

    const desPitch = clamp(Math.atan2(Fbx, Fy), -0.58, 0.58);
    const desRoll = clamp(-Math.atan2(Fbz, Fxy), -0.58, 0.58);
    const desPitchRate = clamp((Fy * dFbx - Fbx * dFy) / Fxy2, -8, 8);
    const desRollRate = clamp(-(dFbz * FmagRaw - Fbz * dFmag) / (FmagRaw * Fxy), -8, 8);

    const actualCos = Math.max(0.5, Math.cos(s.att.pitch) * Math.cos(s.att.roll));
    let Fmag = Fy / actualCos;

    const Ftarget = Fmag + params.lag * dFmag;
    const inertia = TASK.inertia * params.mass / TASK.baseMass;
    const curAlphaRoll = TASK.arm * (-s.motors[0] - s.motors[1] + s.motors[2] + s.motors[3]) / inertia - 0.4 * s.rates.roll;
    const curAlphaPitch = -TASK.arm * (-s.motors[0] + s.motors[1] + s.motors[2] - s.motors[3]) / inertia - 0.4 * s.rates.pitch;

    const tauRoll = inertia * (70 * (desRoll - s.att.roll) + 17 * (desRollRate - s.rates.roll) - 0.6 * params.lag * curAlphaRoll + 0.4 * s.rates.roll);
    const tauPitch = inertia * (70 * (desPitch - s.att.pitch) + 17 * (desPitchRate - s.rates.pitch) - 0.6 * params.lag * curAlphaPitch + 0.4 * s.rates.pitch);
    const yawErr = clamp(wrapAngle(desYaw - s.att.yaw), -0.35, 0.35);
    const tauYaw = inertia * (10 * yawErr - 6 * s.rates.yaw);

    const t = [0, 0, 0, 0];
    for (let i = 0; i < 4; i++) {
      t[i] = Ftarget / 4 +
        tauRoll * MOTOR_Z[i] / (4 * TASK.arm) -
        tauPitch * MOTOR_X[i] / (4 * TASK.arm) +
        tauYaw * SPIN[i] / (4 * TASK.yawCoefficient);
    }

    const wMax = TASK.maxMotorThrust * (1 - params.weakness);
    if (t[wIdx] > wMax) {
      const shift = t[wIdx] - wMax;
      for (let i = 0; i < 4; i++) t[i] -= shift * SPIN[wIdx] * SPIN[i];
    }

    const desired = [0, 0, 0, 0];
    for (let i = 0; i < 4; i++) {
      const scale = (i === wIdx) ? (1 - params.weakness) : 1;
      desired[i] = clamp(t[i] / scale, 0, TASK.maxMotorThrust);
    }

    const cmdThrust = (desired[0] + desired[1] + desired[2] + desired[3]) / (4 * TASK.maxMotorThrust);
    const cmdTRoll = TASK.arm * (-desired[0] - desired[1] + desired[2] + desired[3]);
    const cmdTPitch = -TASK.arm * (-desired[0] + desired[1] + desired[2] - desired[3]);
    const cmdTYaw = TASK.yawCoefficient * (desired[0] - desired[1] + desired[2] - desired[3]);

    const dtSub = TASK.dt / TASK.substeps;
    const solveAxis = (axis, cmdT) => {
      let e = (cmdT / inertia + 13 * s.rates[axis] - 22 * s.integral[axis]) / (65 + 22 * dtSub);
      const intNew = clamp(s.integral[axis] + e * dtSub, -0.35, 0.35);
      if (intNew !== s.integral[axis] + e * dtSub) {
        e = (cmdT / inertia + 13 * s.rates[axis] - 22 * intNew) / 65;
      }
      return s.att[axis] + e + 0.5 * s.rates[axis] * dtSub;
    };

    const action = {
      thrust: clamp(cmdThrust, 0, 1),
      roll: clamp(solveAxis("roll", cmdTRoll), -0.6, 0.6),
      pitch: clamp(solveAxis("pitch", cmdTPitch), -0.6, 0.6),
      yawRate: clamp(s.rates.yaw + cmdTYaw / (8 * inertia), -2, 2),
    };

    for (let sub = 0; sub < TASK.substeps && !simState.reason; sub++) {
      integrate(simState, action, params, dtSub);
      integrate(myState, action, params, dtSub);
    }
  }
  return { seed, success: simState.reason === "landed", reason: simState.reason || "time limit", gates: simState.gateIndex, t: +simState.t.toFixed(2) };
}

let pass = 0;
for (let s = 501; s <= 2000; s++) {
  const r = runTest(s);
  if (r.success) pass++;
  else console.log("FAIL:", r);
}
console.log(`501..2000: ${pass}/1500 passed`);
'

