        const excess = t_post[wIdx] - wMax;
        const shift = excess * SPIN[wIdx];
        for (let i = 0; i < 4; i++) t_post[i] -= shift * SPIN[i];
      }

      const d = [0, 0, 0, 0];
      for (let i = 0; i < 4; i++) {
        const scale = (i === wIdx) ? wScale : 1;
        d[i] = clamp(t_post[i] / scale, 0, TASK.maxMotorThrust);
      }

      const thrustCmd = (d[0] + d[1] + d[2] + d[3]) / (4 * TASK.maxMotorThrust);
      const tauRollCmd = TASK.arm * (d[0] * MOTOR_Z[0] + d[1] * MOTOR_Z[1] + d[2] * MOTOR_Z[2] + d[3] * MOTOR_Z[3]);
      const tauPitchCmd = -TASK.arm * (d[0] * MOTOR_X[0] + d[1] * MOTOR_X[1] + d[2] * MOTOR_X[2] + d[3] * MOTOR_X[3]);
      const tauYawCmd = TASK.yawCoefficient * (d[0] * SPIN[0] + d[1] * SPIN[1] + d[2] * SPIN[2] + d[3] * SPIN[3]);

      const dtSub = 0.005;
      const kE = 65 + 22 * dtSub;
      const rollCmd = myState.att.roll + (tauRollCmd / inertia + 13 * myState.rates.roll - 22 * myState.integral.roll) / kE;
      const pitchCmd = myState.att.pitch + (tauPitchCmd / inertia + 13 * myState.rates.pitch - 22 * myState.integral.pitch) / kE;
      const yawRateCmd = myState.rates.yaw + tauYawCmd / (8 * inertia);

      const action = {
        thrust: clamp(thrustCmd, 0, 1),
        roll: clamp(rollCmd, -0.6, 0.6),
        pitch: clamp(pitchCmd, -0.6, 0.6),
        yawRate: clamp(yawRateCmd, -2, 2),
      };

      for (let sub = 0; sub < 2 && !state.reason; sub++) {
        integrate(state, action, params, 0.005);
        integrate(myState, action, params, 0.005);
      }
